def transform(grid):
    """Decode the marked rectangle boundaries as a cell pattern."""
    # The thin 0 tracks describe a rectangle; output the rectangle's interior.
    # The endpoint markers show the two horizontal boundaries; left/right rails
    # are the 0 cells at the edges, with the top/bottom edge extending across.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = 5
    return out

